import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { texture, uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const group = new ThreeGroup();

  // Create backdrop plane (engineered gradient surface) to fulfill stage requirements
  const backdropGeo = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial();

  // Set up vertical engineered gradient for the stage
  const vUv = uv();
  const colorBottom = vec3(new Color(colors.surface).multiplyScalar(0.7));
  const colorTop = vec3(new Color(colors.ink));
  backdropMat.colorNode = mix(colorBottom, colorTop, vUv.y);

  const backdrop = new ThreeMesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Core visual plane: The CTA image texture / decor orb
  const ctaGeo = new PlaneGeometry(2.4, 1.5);
  const ctaMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      ctaMat.colorNode = texture(tex);
      ctaMat.needsUpdate = true;
      gsap.to(ctaMat, { opacity: 1, duration: 0.8, ease: 'power2.out' });
    }).catch((err) => {
      console.warn('Failed to load CTA image', err);
      // Fallback engineered visual accent if image fails
      const fallbackColor = vec3(new Color(colors.accent));
      ctaMat.colorNode = mix(fallbackColor, vec3(new Color(colors.ink)), vUv.y);
      gsap.to(ctaMat, { opacity: 1, duration: 0.4 });
    });
  } else {
    // Elegant fallback if no image provided
    ctaMat.colorNode = vec3(new Color(colors.surface));
    gsap.to(ctaMat, { opacity: 1, duration: 0.4 });
  }

  const ctaMesh = new ThreeMesh(ctaGeo, ctaMat);
  ctaMesh.position.set(0, 0, 0);
  group.add(ctaMesh);

  // Gently introduce visual entrance animation on load
  gsap.fromTo(ctaMesh.position, 
    { y: -0.2 }, 
    { y: 0, duration: 0.9, ease: 'power4.out', delay: 0.1 }
  );

  // Safe empty cleanup
  group.userData = {
    handlers: {},
    cleanup() {
      backdropGeo.dispose();
      backdropMat.dispose();
      ctaGeo.dispose();
      ctaMat.dispose();
      gsap.killTweensOf(ctaMesh.position);
      gsap.killTweensOf(ctaMat);
    }
  };

  return group;
}
